    return false;
}

// Determine the comparison operator based on allow_point_touch
auto cmp_min = allow_point_touch ? std::less_equal<double>() : std::less<double>();
auto cmp_max = allow_point_touch ? std::greater_equal<double>() : std::greater<double>();

// Check overlap in each dimension
bool overlap_x = !(box1.Max[0] < box2.Min[0] || box2.Max[0] < box1.Min[0]);
bool overlap_y = !(box1.Max[1] < box2.Min[1] || box2.Max[1] < box1.Min[1]);
bool overlap_z = !(box1.Max[2] < box2.Min[2] || box2.Max[2] < box1.Min[2]);

// If no overlap in any dimension, return false
if (!overlap_x || !overlap_y || !overlap_z) {
    return false;
}

// If containment mode is enabled, check if box1 fully contains box2
if (box1_must_contain_box2) {
    bool contains_x = cmp_min(box1.Min[0], box2.Min[0]) && cmp_max(box1.Max[0], box2.Max[0]);
    bool contains_y = cmp_min(box1.Min[1], box2.Min[1]) && cmp_max(box1.Max[1], box2.Max[1]);
    bool contains_z = cmp_min(box1.Min[2], box2.Min[2]) && cmp_max(box1.Max[2], box2.Max[2]);
    return contains_x && contains_y && contains_z;
}

// Otherwise, any overlap is sufficient
return true;

